INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "周宝遣丁从实夺常州，张郁奔海陵", "start_year": 886, "end_year": 886, "time_original": "光启二年六月后条；具体日未载", "dynasty": "唐", "description": "镇海节度使周宝遣丁从实袭常州，逐张郁；张郁投奔镇守海陵的高霸。", "phases": [], "location_name": "常州、海陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9606c7f9-84b0-516d-b0de-0a811e23d20d"}, {"title": "秦宗权陷许州并杀鹿晏弘", "start_year": 886, "end_year": 886, "time_original": "光启二年秋七月", "dynasty": "唐", "description": "秦宗权攻陷许州，杀时任节度使鹿晏弘。", "phases": [], "location_name": "许州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ead99f5e-d022-5568-b4d5-baa64c0744cc"}, {"title": "王行瑜攻兴州，杨晟退往文州", "start_year": 886, "end_year": 886, "time_original": "光启二年七月条；具体日未载", "dynasty": "唐", "description": "王行瑜进攻兴州，感义节度使杨晟弃镇往文州；朝廷命李鋋、李茂贞、陈佩屯大唐峰抵御。", "phases": [], "location_name": "兴州、文州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d88b7f8a-2aa1-5ddc-b134-f937148009ba"}, {"title": "钦化军改称武安，周岳任节度使", "start_year": 886, "end_year": 886, "time_original": "光启二年七月条；具体日未载", "dynasty": "唐", "description": "《通鉴》电子底本记钦化军改号武安，以衡州刺史周岳为节度使；原文首二字作“要命”，有疑字。", "phases": [], "location_name": "武安军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ed4ac922-590d-5999-b8d3-f5291ec83c68"}, {"title": "李全忠去世，李匡威为卢龙留后（底本缺字）", "start_year": 886, "end_year": 886, "time_original": "光启二年八月", "dynasty": "唐", "description": "仓库电子底本作“李忠薨，以其子匡威为留后”；同卷固定版作“李全忠薨”，据前后任卢龙者接续为李全忠去世，子李匡威为留后。", "phases": [], "location_name": "卢龙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ab6065fa-48d4-5fb2-81a3-2effa4e5f97a"}, {"title": "王潮攻下泉州并杀廖彦若", "start_year": 886, "end_year": 886, "time_original": "光启二年八月条；具体日未载", "dynasty": "唐", "description": "王潮攻下泉州，杀刺史廖彦若。", "phases": [], "location_name": "泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0c1e94be-b95b-5fe5-b606-f7f0a648b7c5"}, {"title": "王潮降陈岩并获泉州刺史任命", "start_year": 886, "end_year": 886, "time_original": "泉州陷落之后；具体日未载", "dynasty": "唐", "description": "王潮未攻福州，遣使向福建观察使陈岩投降；陈岩上表任王潮为泉州刺史。", "phases": [], "location_name": "泉州、福建", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2842b9c9-bdd4-5145-9b9e-4972f7aa0d9d"}, {"title": "王绪被王潮幽禁后自杀", "start_year": 886, "end_year": 886, "time_original": "王潮据泉州之后；具体日未载", "dynasty": "唐", "description": "王潮将王绪幽禁于别馆，王绪自杀。", "phases": [], "location_name": "泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "86999818-2103-584a-b1fb-e70d7ed260c8"}, {"title": "李鋋击退张行实于大唐峰", "start_year": 886, "end_year": 886, "time_original": "光启二年九月", "dynasty": "唐", "description": "朱玫部将张行实进攻大唐峰，李鋋等将其击退。", "phases": [], "location_name": "大唐峰", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c8ffc64d-5fcd-5795-81b6-6c02de4dd717"}, {"title": "满存败邠军并收复兴州", "start_year": 886, "end_year": 886, "time_original": "光启二年九月", "dynasty": "唐", "description": "满存击败邠军、收复兴州，进守万仞寨。", "phases": [], "location_name": "兴州、万仞寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b29d8836-75a8-5172-8831-9ad61bdb9c97"}, {"title": "李克修攻孟方立并连取诸镇", "start_year": 886, "end_year": 886, "time_original": "光启二年九月甲午及其前后", "dynasty": "唐", "description": "李克修攻孟方立，甲午于焦冈擒其将吕臻，攻取故镇、武安、临洺、邯郸、沙河，任安金俊为邢州刺史。", "phases": [], "location_name": "焦冈、邢州诸镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c4c275dc-4d1f-5ae9-b1f3-33845e5bf5e3"}, {"title": "长安百官劝襄王煴即位", "start_year": 886, "end_year": 886, "time_original": "光启二年九月后、十月前", "dynasty": "唐", "description": "太子太师裴璩等长安百官劝襄王煴即皇帝位。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "62c8c520-0d3a-55d1-bc91-dd94bec9b8f9"}, {"title": "襄王煴即皇帝位，改元建贞", "start_year": 886, "end_year": 886, "time_original": "光启二年冬十月", "dynasty": "唐", "description": "襄王煴在长安即皇帝位，改元建贞，遥尊在兴元的僖宗为太上元皇帝。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f1f2402b-f399-5d5c-ae72-8ea074692bce"}, {"title": "董昌许钱镠取越州后授杭州", "start_year": 886, "end_year": 886, "time_original": "光启二年十月条；具体日未载", "dynasty": "唐", "description": "董昌向钱镠提出取越州后将杭州交给钱镠，钱镠同意并领兵出征。", "phases": [], "location_name": "越州、杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4301b1bb-46eb-5f2d-9caa-81e8d3a8ce13"}, {"title": "钱镠进兵丰山，鲍君福归降", "start_year": 886, "end_year": 886, "time_original": "董昌建议后；具体月日未载", "dynasty": "唐", "description": "钱镠自诸暨进兵，经平水、曹娥埭；浙东将鲍君福率众降之。钱镠屡败浙东军，进屯丰山。", "phases": [], "location_name": "诸暨、平水、曹娥埭、丰山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "462dd64c-5ae5-56c0-9fe4-f553a5ba2cb7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

